{!REQUIRESCRIPT("/soap/ajax/32.0/connection.js")} 
{!REQUIRESCRIPT("/soap/ajax/32.0/apex.js")} 

var record = new sforce.SObject("Inventory__c"); 
var result = sforce.apex.execute('SDReleaseAndUnblock', 'sdRelUnblck',{objID: "{!Inventory__c.Id}"}); 
console.log('-----result----'+result);
if(result == 'Error9'){ 
alert('You are not authorized to unblock and release this Unit.'); 
} 
else if(result == 'Error8'){ 
alert('You can unblock and release only for Blocked inventory.'); 
} 
else if(result == 'Error7'){ 
alert('You are not authorized to unblock this Unit.'); 
} 
else if(result == 'Error6'){ 
alert('You can unblock unit only for Blocked inventory.'); 
} 
else if(result == 'Success'){ 
alert('Successfully unblocked this unit'); 
location.reload(); 
}
